val KadaiPurple=Color(0xFF7C3AED)
val KadaiPurpleDark=Color(0xFF4C1D95)
val KadaiPurpleSoft=Color(0xFFF3E8FF)
val KadaiPurpleHome=Color(0xFFF5EEFF)

data class UserAccount(val id:String=UUID.randomUUID().toString(),val email:String,val username:String,val password:String,val role:String,val shop:String="",val phone:String="",val address:String="")
data class SellerProfile(val shop:String,val phone:String,val address:String)
data class Product(val id:String=UUID.randomUUID().toString(),val name:String,val price:Double,val shop:String,val category:String,val area:String,val image:String,val sellerPhone:String,val sellerAddress:String,val sellerId:String="sample",val stock:Int=10)
data class CartLine(val product:Product,val qty:Int)
data class AppNotice(val id:String=UUID.randomUUID().toString(),val target:String,val title:String,val message:String,val createdAt:Long=System.currentTimeMillis())
data class Order(val id:String=UUID.randomUUID().toString().take(8).uppercase(),val buyerId:String="",val buyerPhone:String="",val lines:List<CartLine>,val delivery:String,val district:String="",val deliveryAddress:String="",val deliveryLocation:String="",val deliveryFee:Double=0.0,val paymentMethod:String="Cash",val total:Double,val runnerName:String="",val runnerPhone:String="",val sellerStatus:String="New",val runnerStatus:String="Waiting",val createdAt:Long=System.currentTimeMillis(),val deliveredAt:Long?=null)

fun tr(lang:String,ms:String,en:String)=if(lang=="English")en else ms
fun deliveryFeeFor(district:String)=when(district){"Brunei-Muara"->3.0;"Tutong"->5.0;"Kuala Belait"->7.0;"Temburong"->9.0;else->3.0}
fun assignMarketplaceRunner():Pair<String,String>{val runners=listOf("Hakim" to "+673 7XX 1010","Faris" to "+673 8XX 2020","Azim" to "+673 7XX 3030","Rizal" to "+673 8XX 4040");return runners.random()}
fun addCart(c:List<CartLine>,p:Product):List<CartLine>{if(p.stock<=0)return c;val x=c.toMutableList();val i=x.indexOfFirst{it.product.id==p.id};if(i>=0){if(x[i].qty<p.stock)x[i]=x[i].copy(qty=x[i].qty+1)}else x.add(CartLine(p,1));return x}
fun removeOne(c:List<CartLine>,p:Product):List<CartLine>{val x=c.toMutableList();val i=x.indexOfFirst{it.product.id==p.id};if(i>=0){if(x[i].qty>1)x[i]=x[i].copy(qty=x[i].qty-1)else x.removeAt(i)};return x}
fun removeItem(c:List<CartLine>,p:Product)=c.filterNot{it.product.id==p.id}
fun sellerOrderValue(order:Order,sellerId:String)=order.lines.filter{it.product.sellerId==sellerId}.sumOf{it.product.price*it.qty}
fun isBruneiPhone(phone:String)=Regex("^\\+673[0-9]{7}$").matches(phone.replace(" ",""))
fun isValidEmail(email:String)=android.util.Patterns.EMAIL_ADDRESS.matcher(email.trim()).matches()
fun startOfWeek(now:Long):Long{val c=Calendar.getInstance().apply{timeInMillis=now;set(Calendar.DAY_OF_WEEK,firstDayOfWeek);set(Calendar.HOUR_OF_DAY,0);set(Calendar.MINUTE,0);set(Calendar.SECOND,0);set(Calendar.MILLISECOND,0)};return c.timeInMillis}
fun startOfMonth(now:Long):Long{val c=Calendar.getInstance().apply{timeInMillis=now;set(Calendar.DAY_OF_MONTH,1);set(Calendar.HOUR_OF_DAY,0);set(Calendar.MINUTE,0);set(Calendar.SECOND,0);set(Calendar.MILLISECOND,0)};return c.timeInMillis}
fun startOfYear(now:Long):Long{val c=Calendar.getInstance().apply{timeInMillis=now;set(Calendar.DAY_OF_YEAR,1);set(Calendar.HOUR_OF_DAY,0);set(Calendar.MINUTE,0);set(Calendar.SECOND,0);set(Calendar.MILLISECOND,0)};return c.timeInMillis}
fun openWhatsApp(context:Context,phone:String){val clean=phone.filter(Char::isDigit);runCatching{context.startActivity(Intent(Intent.ACTION_VIEW,Uri.parse("https://wa.me/$clean")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))}}
fun openSellerMap(context:Context,address:String){val target=if(address.startsWith("http://")||address.startsWith("https://"))Uri.parse(address) else Uri.parse("geo:0,0?q=${Uri.encode(address)}");runCatching{context.startActivity(Intent(Intent.ACTION_VIEW,target).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))}}
fun deliveryEta(order:Order,language:String)=when{order.runnerStatus=="Arrived"->tr(language,"Sudah sampai","Arrived");order.runnerStatus=="OnTheWay"->tr(language,"10–20 minit lagi","10–20 min remaining");order.runnerStatus=="Accepted"->tr(language,"20–30 minit lagi","20–30 min remaining");order.sellerStatus=="Packed"->tr(language,"30–45 minit lagi","30–45 min remaining");else->tr(language,"Menunggu seller siapkan barang","Waiting for seller to prepare order")}

class MainActivity:ComponentActivity(){override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);setContent{KadaiKuApp()}}}

@Composable fun SplashScreen(){val slideX=remember{Animatable(-360f)};val logoScale=remember{Animatable(.72f)};val titleScale=remember{Animatable(.94f)};LaunchedEffect(Unit){slideX.animateTo(0f,tween(520,easing=FastOutSlowInEasing));titleScale.animateTo(1f,tween(260,easing=FastOutSlowInEasing));delay(180);logoScale.animateTo(1.08f,tween(320,easing=FastOutSlowInEasing));delay(100);logoScale.animateTo(18f,tween(700,easing=FastOutSlowInEasing))};Box(Modifier.fillMaxSize().background(Brush.verticalGradient(listOf(KadaiPurpleDark,KadaiPurple,Color(0xFFA855F7)))),contentAlignment=Alignment.Center){Column(horizontalAlignment=Alignment.CenterHorizontally){Text("KadaiKu",modifier=Modifier.offset{IntOffset(slideX.value.roundToInt(),0)}.scale(titleScale.value),style=MaterialTheme.typography.displaySmall,fontWeight=FontWeight.Black,color=Color.White);Spacer(Modifier.height(22.dp));Box(Modifier.size(116.dp).scale(logoScale.value).clip(RoundedCornerShape(34.dp)).background(Color.White),contentAlignment=Alignment.Center){Text("K",style=MaterialTheme.typography.displayMedium,fontWeight=FontWeight.Black,color=KadaiPurple)};Spacer(Modifier.height(20.dp));Text("Brunei 🇧🇳",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold,color=Color.White);Text("Local marketplace",color=Color.White.copy(alpha=.88f))}}}
@Composable fun CartBadgeIcon(count:Int){Box(Modifier.size(28.dp),contentAlignment=Alignment.Center){Text("🛒");if(count>0){Box(Modifier.align(Alignment.TopEnd).size(16.dp).clip(CircleShape).background(Color.Red),contentAlignment=Alignment.Center){Text(if(count>99)"99+" else count.toString(),color=Color.White,style=MaterialTheme.typography.labelSmall,fontWeight=FontWeight.Bold)}}}}

fun openRegistrationConfirmationEmail(context:Context,email:String,username:String){val subject=Uri.encode("KadaiKu Brunei - Account Registration");val body=Uri.encode("Hi $username,\n\nYour KadaiKu Brunei account has been registered successfully.\n\nWelcome to KadaiKu Brunei 🇧🇳\n\nKadaiKu Team");val uri=Uri.parse("mailto:${Uri.encode(email)}?subject=$subject&body=$body");runCatching{context.startActivity(Intent(Intent.ACTION_SENDTO,uri).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))}}

@OptIn(ExperimentalMaterial3Api::class)
@Composable fun KadaiKuApp(){
    val context=LocalContext.current;val prefs=remember{context.getSharedPreferences("kadaiku_login",Context.MODE_PRIVATE)}
    var splash by remember{mutableStateOf(true)};var language by remember{mutableStateOf("Melayu")};var pushNotifications by remember{mutableStateOf(true)}
    var rememberedUsername by remember{mutableStateOf(prefs.getString("username","").orEmpty())};var rememberedPassword by remember{mutableStateOf(prefs.getString("password","").orEmpty())};var rememberLogin by remember{mutableStateOf(prefs.getBoolean("remember",false))}
    var accounts by remember{mutableStateOf(listOf<UserAccount>())};var currentUser by remember{mutableStateOf<UserAccount?>(null)};var showRegister by remember{mutableStateOf(false)};var tab by remember{mutableIntStateOf(0)}
    var products by remember{mutableStateOf(listOf(Product(name="Kek Coklat Premium",price=15.0,shop="Dapur Aisyah",category="Makanan",area="Gadong",image="🍰",sellerPhone="+673 7123456",sellerAddress="Gadong, Brunei-Muara",sellerId="sample-aisyah",stock=12),Product(name="Perfume Oud",price=20.0,shop="Brunei Fragrance",category="Beauty",area="Kiulap",image="🧴",sellerPhone="+673 8123456",sellerAddress="Kiulap, Brunei-Muara",sellerId="sample-fragrance",stock=8),Product(name="Baju Melayu",price=35.0,shop="Kedai Kita",category="Fashion",area="Bandar",image="👕",sellerPhone="+673 7234567",sellerAddress="Bandar Seri Begawan",sellerId="sample-kita",stock=10),Product(name="Frozen Food Combo",price=12.0,shop="Mama's Frozen",category="Makanan",area="Tutong",image="🥟",sellerPhone="+673 8345678",sellerAddress="Tutong, Brunei",sellerId="sample-mama",stock=15)))}
    var cart by remember{mutableStateOf(listOf<CartLine>())};var orders by remember{mutableStateOf(listOf<Order>())};var notices by remember{mutableStateOf(listOf<AppNotice>())};var search by remember{mutableStateOf("")};var selectedProduct by remember{mutableStateOf<Product?>(null)};var selectedSellerId by remember{mutableStateOf<String?>(null)};var historyOrder by remember{mutableStateOf<Order?>(null)};var showSeller by remember{mutableStateOf(false)};var showAdd by remember{mutableStateOf(false)};var showSupport by remember{mutableStateOf(false)};var showSettings by remember{mutableStateOf(false)};var supportX by remember{mutableStateOf(0f)};var supportY by remember{mutableStateOf(0f)};var playedNoticeCount by remember{mutableIntStateOf(0)}
    LaunchedEffect(Unit){delay(1950);splash=false};if(splash){SplashScreen();return}
    if(currentUser==null){if(showRegister) RegisterScreen(language,{language=it},{showRegister=false}){e,u,p,r,s,ph,loc->val a=UserAccount(email=e,username=u,password=p,role=r,shop=s,phone=ph,address=loc);accounts=accounts+a;openRegistrationConfirmationEmail(context,e,u);currentUser=a;showRegister=false}else LoginScreen(language,{language=it},if(rememberLogin)rememberedUsername else "",if(rememberLogin)rememberedPassword else "",rememberLogin,{u,p,rememberMe->accounts.firstOrNull{it.username.equals(u,true)&&it.password==p}?.let{currentUser=it;rememberLogin=rememberMe;if(rememberMe){rememberedUsername=u;rememberedPassword=p;prefs.edit().putBoolean("remember",true).putString("username",u).putString("password",p).apply()}else{rememberedUsername="";rememberedPassword="";prefs.edit().clear().apply()}}},{showRegister=true});return}
    val user=currentUser!!;val sellerProfile=SellerProfile(user.shop.ifBlank{tr(language,"Kedai Saya","My Shop")},user.phone,user.address);val buyerOrders=orders.filter{it.buyerId==user.id};val visibleProducts=products.filter{it.stock>0}.filter{search.isBlank()||it.name.contains(search,true)||it.shop.contains(search,true)||it.category.contains(search,true)};val cartCount=cart.sumOf{it.qty};val sellerNotices=if(user.role=="Seller"&&pushNotifications)notices.filter{it.target==user.id}else emptyList()
    LaunchedEffect(sellerNotices.size,user.id){if(user.role=="Seller"&&sellerNotices.size>playedNoticeCount){runCatching{RingtoneManager.getRingtone(context,RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION))?.play()};playedNoticeCount=sellerNotices.size}}
    LaunchedEffect(orders.map{it.id to it.sellerStatus}){orders.filter{it.delivery!="Pickup"&&it.sellerStatus=="Packed"&&it.runnerStatus=="Waiting"&&it.deliveredAt==null}.forEach{order->delay(3500);orders=orders.map{if(it.id==order.id)it.copy(runnerStatus="Accepted")else it};delay(5000);orders=orders.map{if(it.id==order.id&&it.deliveredAt==null)it.copy(runnerStatus="OnTheWay")else it};delay(7000);orders=orders.map{if(it.id==order.id&&it.deliveredAt==null)it.copy(runnerStatus="Arrived",deliveredAt=System.currentTimeMillis())else it}}}
    Box(Modifier.fillMaxSize()){
        Scaffold(containerColor=Color(0xFFFCFAFF),topBar={CenterAlignedTopAppBar(title={Text("KadaiKu 🇧🇳",fontWeight=FontWeight.ExtraBold,color=KadaiPurpleDark)})},bottomBar={NavigationBar{listOf(tr(language,"Home","Home"),tr(language,"Cari","Search"),tr(language,"Troli","Cart"),tr(language,"Orders","Orders"),tr(language,"Profil","Profile")).forEachIndexed{i,l->NavigationBarItem(selected=tab==i,onClick={tab=i},icon={if(i==2)CartBadgeIcon(cartCount) else Text(when(i){0->"🏠";1->"🔎";3->"📦";else->"👤"})},label={Text(l)})}}}){pad->when(tab){0->Home(visibleProducts,search,{search=it},{if(user.role=="Seller")showSeller=true},{cart=addCart(cart,it)},{selectedProduct=it},{selectedSellerId=it.sellerId},Modifier.padding(pad),user.role=="Seller",language);1->SearchPage(visibleProducts,search,{search=it},{cart=addCart(cart,it)},{selectedProduct=it},{selectedSellerId=it.sellerId},Modifier.padding(pad),language);2->CartPage(cart,{cart=removeOne(cart,it)},{cart=addCart(cart,it)},{cart=removeItem(cart,it)},{buyerPhone,delivery,district,address,location,fee,payment,total->if(cart.isNotEmpty()){val runner=if(delivery=="Pickup")"" to "" else assignMarketplaceRunner();val order=Order(buyerId=user.id,buyerPhone=buyerPhone,lines=cart.map{it.copy()},delivery=delivery,district=district,deliveryAddress=address,deliveryLocation=location,deliveryFee=fee,paymentMethod=payment,total=total,runnerName=runner.first,runnerPhone=runner.second);orders=orders+order;products=products.map{p->val q=cart.firstOrNull{it.product.id==p.id}?.qty?:0;if(q>0)p.copy(stock=(p.stock-q).coerceAtLeast(0))else p};if(pushNotifications)order.lines.groupBy{it.product.sellerId}.forEach{(sellerId,lines)->if(!sellerId.startsWith("sample-"))notices=notices+AppNotice(target=sellerId,title="New order #${order.id}",message="${lines.sumOf{it.qty}} item(s) ordered")};cart=emptyList();tab=3}},Modifier.padding(pad),language);3->OrdersPage(buyerOrders,{id->orders=orders.map{if(it.id==id&&it.deliveredAt==null)it.copy(deliveredAt=System.currentTimeMillis())else it}},{historyOrder=it},Modifier.padding(pad),language);else->ProfilePage(user,sellerNotices,{if(user.role=="Seller")showSeller=true},{showSettings=true},{currentUser=null;cart=emptyList();tab=0},Modifier.padding(pad),language)}}
        FloatingActionButton(onClick={showSupport=true},containerColor=Color(0xFF20C56B),contentColor=Color.White,shape=CircleShape,modifier=Modifier.align(Alignment.BottomEnd).padding(16.dp).offset{IntOffset(supportX.roundToInt(),supportY.roundToInt())}.pointerInput(Unit){detectDragGestures{c,d->c.consume();supportX+=d.x;supportY+=d.y}}){Text("💬")}
    }
    selectedProduct?.let{p->ProductDetailSheet(p,{selectedProduct=null},{cart=addCart(cart,p)},{selectedProduct=null;selectedSellerId=p.sellerId},language)}
    selectedSellerId?.let{id->products.firstOrNull{it.sellerId==id}?.let{a->SellerStoreSheet(id,products,a,{selectedSellerId=null},{cart=addCart(cart,it)},{selectedProduct=it;selectedSellerId=null},language)}}
    historyOrder?.let{HistoryDetailSheet(it,{historyOrder=null},language)}
    if(showSupport)CustomerServiceSheet({showSupport=false},language)
    if(showSettings)SettingsSheet(user,{showSettings=false},language,{language=it},pushNotifications,{pushNotifications=it},{old,new->if(old==currentUser?.password&&new.length>=8){val updated=currentUser!!.copy(password=new);accounts=accounts.map{if(it.id==updated.id)updated else it};currentUser=updated;if(rememberLogin){rememberedPassword=new;prefs.edit().putString("password",new).apply()};true}else false})
    if(showSeller&&user.role=="Seller")SellerSheet({showSeller=false},{showAdd=true},products,orders,sellerProfile,user.id,{id->products=products.filterNot{it.id==id}},{id,status->val before=orders.firstOrNull{it.id==id};if(status=="Cancelled"&&before!=null&&before.sellerStatus!="Cancelled"){products=products.map{p->val restore=before.lines.filter{it.product.sellerId==user.id&&it.product.id==p.id}.sumOf{it.qty};if(restore>0)p.copy(stock=p.stock+restore)else p}};orders=orders.map{if(it.id==id)it.copy(sellerStatus=status)else it}},language)
    if(showAdd&&user.role=="Seller")AddProductDialog(sellerProfile,{showAdd=false},{name,price,cat,image,stock->products=products+Product(name=name,price=price,shop=sellerProfile.shop,category=cat,area=sellerProfile.address,image=image,sellerPhone=sellerProfile.phone,sellerAddress=sellerProfile.address,sellerId=user.id,stock=stock);showAdd=false},language)
}

