@Composable fun LoginScreen(language:String,onLanguage:(String)->Unit,initialUsername:String,initialPassword:String,initialRemember:Boolean,onLogin:(String,String,Boolean)->Unit,onRegister:()->Unit){var u by remember{mutableStateOf(initialUsername)};var p by remember{mutableStateOf(initialPassword)};var show by remember{mutableStateOf(false)};var rememberMe by remember{mutableStateOf(initialRemember)};Column(Modifier.fillMaxSize().padding(24.dp),verticalArrangement=Arrangement.Center){Text("KadaiKu Brunei",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.ExtraBold,color=KadaiPurpleDark);LanguageChooser(language,onLanguage);OutlinedTextField(u,{u=it},label={Text("Username")},modifier=Modifier.fillMaxWidth());OutlinedTextField(p,{p=it},label={Text("Password")},modifier=Modifier.fillMaxWidth(),visualTransformation=if(show)VisualTransformation.None else PasswordVisualTransformation(),trailingIcon={TextButton({show=!show}){Text(if(show)tr(language,"Sembunyi","Hide")else tr(language,"Tunjuk","Show"))}});Row(verticalAlignment=Alignment.CenterVertically){Checkbox(rememberMe,{rememberMe=it});Text(tr(language,"Ingat saya untuk login mudah","Remember me for easier login"))};Button({onLogin(u,p,rememberMe)},Modifier.fillMaxWidth(),colors=ButtonDefaults.buttonColors(containerColor=KadaiPurple)){Text("Login")};TextButton(onRegister,Modifier.fillMaxWidth()){Text(tr(language,"Pengguna baru? Daftar","New user? Register"))}}}
