())};item{OutlinedTextField(phoneDigits,{phoneDigits=it.filter(Char::isDigit).take(7)},label={Text(tr(language,"No. telefon Brunei","Brunei phone number"))},prefix={Text("+673 ")},placeholder={Text("7123456")},modifier=Modifier.fillMaxWidth(),supportingText={Text(tr(language,"Mesti nombor Brunei +673 dan 7 digit","Must be a Brunei +673 number with 7 digits"))})};item{OutlinedTextField(loc,{loc=it},label={Text(tr(language,"Lokasi seller","Seller location"))},placeholder={Text("Google Maps link / coordinates")},modifier=Modifier.fillMaxWidth())}};item{Button({onRegister(email,u,p,role,shop,fullPhone,loc)},Modifier.fillMaxWidth(),enabled=emailValid&&u.isNotBlank()&&p.length>=8&&sellerValid,colors=ButtonDefaults.buttonColors(containerColor=KadaiPurple)){Text(tr(language,"Buat Akaun","Create Account"))}};item{TextButton(onBack,Modifier.fillMaxWidth()){Text(tr(language,"Kembali","Back"))}}}}

