nt=Arrangement.spacedBy(6.dp)){Text(tr(language,"Self Pickup Seller","Self Pickup Seller"),fontWeight=FontWeight.Bold,color=KadaiPurpleDark);Text("🏪 ${seller.shop}");Text("📞 ${seller.sellerPhone}",color=KadaiPurple,modifier=Modifier.clickable{openWhatsApp(context,seller.sellerPhone)});Text("📍 ${seller.sellerAddress}",color=KadaiPurple,modifier=Modifier.clickable{openSellerMap(context,seller.sellerAddress)});Text(tr(language,"Tap nombor untuk WhatsApp • Tap lokasi untuk Google Maps","Tap phone for WhatsApp • Tap location for Google Maps"),style=MaterialTheme.typography.bodySmall,color=Color.Gray)}};if(pickupReady){Button(onDelivered,Modifier.fillMaxWidth(),colors=ButtonDefaults.buttonColors(containerColor=Color(0xFF16A34A))){Text(tr(language,"Complete Pickup","Complete Pickup"))}}}else{Card(Modifier.fillMaxWidth(),colors=CardDefaults.cardColors(containerColor=Color(0xFFF7F7FB))){Column(Modifier.padding(10.dp)){Text("⏱️ ${tr(language,"ETA Delivery","Delivery ETA")}",fontWeight=FontWeight.Bold,color=KadaiPurpleDark);Text(deliveryEta(order,language),fontWeight=FontWeight.ExtraBold,color=KadaiPurple)}};OutlinedButton({showTracking=!showTracking},Modifier.fillMaxWidth()){Text(if(showTracking)tr(language,"Tutup Tracking","Hide Tracking")else tr(language,"📍 Lihat Tracking","📍 View Tracking"))};if(showTracking)RouteMapCard(order,language)}}}}
