@OptIn(ExperimentalMaterial3Api::class) @Composable fun HistoryDetailSheet(order:Order,onClose:()->Unit,language:String){ModalBottomSheet(onDismissRequest=onClose){LazyColumn(contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Text(tr(language,"Detail Order","Order Details"),style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold,color=KadaiPurpleDark);Text("#${order.id}");Text("${tr(language,"Payment","Payment")}: ${order.paymentMethod}")};items(order.lines){l->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Row(verticalAlignment=Alignment.CenterVertically){ProductImage(l.product.image,Modifier.size(54.dp));Spacer(Modifier.width(10.dp));Column{Text(l.product.name,fontWeight=FontWeight.Bold);Text("Qty ${l.qty}");Text("B$%.2f".format(l.product.price*l.qty))}};HorizontalDivider(Modifier.padding(vertical=8.dp));Text(tr(language,"Detail Seller","Seller Details"),fontWeight=FontWeight.Bold,color=KadaiPurpleDark);Text("🏪 ${l.product.shop}");Text("📞 ${l.product.sellerPhone}");Text("📍 ${l.product.sellerAddress}")}}};item{Text("${tr(language,"Jumlah","Total")}: B$%.2f".format(order.total),fontWeight=FontWeight.Bold);if(order.delivery!="Pickup"){Text("Delivery: ${order.district} • B$%.2f".format(order.deliveryFee));if(order.deliveryAddress.isNotBlank())Text("🏠 ${order.deliveryAddress}");if(order.deliveryLocation.isNotBlank())Text("📍 ${order.deliveryLocation}")}}}}}
@OptIn(ExperimentalMaterial3Api::class) @Composable fun CustomerServiceSheet(onClose:()->Unit,language:String){ModalBottomSheet(onDismissRequest=onClose){Column(Modifier.padding(24.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Text("💬 KadaiKu Customer Service",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold,color=KadaiPurpleDark);Text(tr(language,"Ada masalah dengan order atau delivery? Email customer service KadaiKu.","Having an issue with an order or delivery? Email KadaiKu customer service."));Card(colors=CardDefaults.cardColors(containerColor=KadaiPurpleSoft)){Text("✉️ Kadaiku@gmail.com",modifier=Modifier.padding(16.dp),fontWeight=FontWeight.Bold,color=KadaiPurpleDark)}}}}

@Composable fun SalesStatCard(label:String,sales:Double,orders:Int,m:Modifier=Modifier){Card(m,colors=CardDefaults.cardColors(containerColor=KadaiPurpleSoft)){Column(Modifier.padding(12.dp)){Text(label,fontWeight=FontWeight.Bold,color=KadaiPurpleDark);Text("B$%.2f".format(sales),style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.ExtraBold);Text("$orders orders",style=MaterialTheme.typography.bodySmall,color=Color.Gray)}}}
@Composable fun SellerOrderActionCard(order:Order,sellerId:String,onStatus:(String,String)->Unit,language:String){val context=LocalContext.current;Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Text("#${order.id}",fontWeight=FontWeight.Bold);order.lines.filter{it.product.sellerId==sellerId}.forEach{Text("• ${it.product.name} × ${it.qty}")};Text("📞 ${tr(language,"Buyer","Buyer")}: ${order.buyerPhone}",color=KadaiPurple,fontWeight=FontWeight.Bold,modifier=Modifier.clickable{openWhatsApp(context,order.buyerPhone)});Text("B$%.2f".format(sellerOrderValue(order,sellerId)),fontWeight=FontWeight.Bold);Text("${tr(language,"Status","Status")}: ${order.sellerStatus}");when(order.sellerStatus){"New"->Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Button({onStatus(order.id,"Accepted")},Modifier.weight(1f),colors=ButtonDefaults.buttonColors(containerColor=KadaiPurple)){Text(tr(language,"Terima Order","Accept Order"))};OutlinedButton({onStatus(order.id,"Cancelled")},Modifier.weight(1f)){Text(tr(language,"Cancel Order","Cancel Order"),color=MaterialTheme.colorScheme.error)}};"Accepted"->Column(verticalArrangement=Arrangement.spacedBy(8.dp)){Button({onStatus(order.id,"Packed")},Modifier.fillMaxWidth(),colors=ButtonDefaults.buttonColors(containerColor=Color(0xFF16A34A))){Text(if(order.delivery=="Pickup")tr(language,"Ready for Pickup","Ready for Pickup")else tr(language,"Sudah Siap Packing","Packed & Ready"))};OutlinedButton({onStatus(order.id,"Cancelled")},Modifier.fillMaxWidth()){Text(tr(language,"Cancel Order & Restore Stock","Cancel Order & Restore Stock"),color=MaterialTheme.colorScheme.error)}};"Packed"->Column(verticalArrangement=Arrangement.spacedBy(8.dp)){Text(if(order.delivery=="Pickup")tr(language,"✅ Ready for Pickup","✅ Ready for Pickup")else tr(language,"✅ Barang siap untuk runner","✅ Ready for runner"),color=Color(0xFF15803D),fontWeight=FontWeight.Bold);OutlinedButton({onStatus(order.id,"Cancelled")},Modifier.fillMaxWidth()){Text(tr(language,"Cancel Order & Restore Stock","Cancel Order & Restore Stock"),color=MaterialTheme.colorScheme.error)}};"Cancelled"->Text(tr(language,"❌ Order dibatalkan • stok dipulangkan","❌ Order cancelled • stock restored"),color=MaterialTheme.colorScheme.error,fontWeight=FontWeight.Bold);"Rejected"->Text(tr(language,"❌ Order ditolak","❌ Order rejected"),color=MaterialTheme.colorScheme.error,fontWeight=FontWeight.Bold)}}}}
@OptIn(ExperimentalMaterial3Api::class) @Composable fun SellerSheet(onClose:()->Unit,onAdd:()->Unit,products:List<Product>,orders:List<Order>,profile:SellerProfile,sellerId:String,onDelete:(String)->Unit,onStatus:(String,String)->Unit,language:String){val mine=products.filter{it.sellerId==sellerId};val sellerOrders=orders.filter{o->o.lines.any{it.product.sellerId==sellerId}};val completed=sellerOrders.filter{it.deliveredAt!=null};val now=System.currentTimeMillis();val weekStart=startOfWeek(now);val monthStart=startOfMonth(now);val yearStart=startOfYear(now);val weekly=completed.filter{(it.deliveredAt?:it.createdAt)>=weekStart};val monthly=completed.filter{(it.deliveredAt?:it.createdAt)>=monthStart};val yearly=completed.filter{(it.deliveredAt?:it.createdAt)>=yearStart};ModalBottomSheet(onDismissRequest=onClose){LazyColumn(contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Text("${profile.shop} Dashboard",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold,color=KadaiPurpleDark);Text("📞 ${profile.phone}");Text("📍 ${profile.address}")};item{Text(tr(language,"Sales Performance","Sales Performance"),fontWeight=FontWeight.Bold)};item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){SalesStatCard(tr(language,"Mingguan","Weekly"),weekly.sumOf{sellerOrderValue(it,sellerId)},weekly.size,Modifier.weight(1f));SalesStatCard(tr(language,"Bulanan","Monthly"),monthly.sumOf{sellerOrderValue(it,sellerId)},monthly.size,Modifier.weight(1f));SalesStatCard(tr(language,"Tahunan","Yearly"),yearly.sumOf{sellerOrderValue(it,sellerId)},yearly.size,Modifier.weight(1f))}};item{Button(onAdd,Modifier.fillMaxWidth(),colors=ButtonDefaults.buttonColors(containerColor=KadaiPurple)){Text(tr(language,"+ Tambah Produk","+ Add Product"))}};item{Text(tr(language,"Order Aktif","Active Orders"),fontWeight=FontWeight.Bold)};items(sellerOrders.filter{it.deliveredAt==null&&it.sellerStatus!="Rejected"&&it.sellerStatus!="Cancelled"}.reversed()){SellerOrderActionCard(it,sellerId,onStatus,language)};val rejected=sellerOrders.filter{it.sellerStatus=="Rejected"||it.sellerStatus=="Cancelled"};if(rejected.isNotEmpty()){item{Text(tr(language,"Order Dibatalkan/Ditolak","Cancelled/Rejected Orders"),fontWeight=FontWeight.Bold,color=MaterialTheme.colorScheme.error)};items(rejected.reversed()){SellerOrderActionCard(it,sellerId,onStatus,language)}};item{Text(tr(language,"Produk Saya","My Products"),fontWeight=FontWeight.Bold)};items(mine){p->Card(Modifier.fillMaxWidth()){Row(Modifier.padding(10.dp)){Column(Modifier.weight(1f)){Text(p.name);Text("Stock ${p.stock}")};TextButton({onDelete(p.id)}){Text(tr(language,"Padam","Delete"))}}}};item{Text(tr(language,"History Seller","Seller History"),fontWeight=FontWeight.Bold)};items(completed){Text("#${it.id} • ✅ ${tr(language,"Selesai","Complete")} • B$%.2f".format(sellerOrderValue(it,sellerId)))}}}}
@Composable fun AddProductDialog(sellerProfile:SellerProfile,onDismiss:()->Unit,onSave:(String,Double,String,String,Int)->Unit,language:String){var n by remember{mutableStateOf("")};var pr by remember{mutableStateOf("")};var cat by remember{mutableStateOf("Makanan")};var stock by remember{mutableStateOf("")};var image by remember{mutableStateOf("")};val launcher=rememberLauncherForActivityResult(ActivityResultContracts.GetContent()){image=it?.toString().orEmpty()};AlertDialog(onDismissRequest=onDismiss,title={Text(tr(language,"Tambah Produk","Add Product"))},text={Column{OutlinedButton({launcher.launch("image/*")}){Text(tr(language,"Pilih gambar","Choose image"))};OutlinedTextField(n,{n=it},label={Text(tr(language,"Nama produk","Product name"))});OutlinedTextField(pr,{pr=it},label={Text("B$")});OutlinedTextField(stock,{stock=it.filter(Char::isDigit)},label={Text(tr(language,"Jumlah stok","Stock quantity"))});OutlinedTextField(cat,{cat=it},label={Text(tr(language,"Kategori","Category"))})}},confirmButton={Button(enabled=n.isNotBlank()&&pr.toDoubleOrNull()!=null&&stock.toIntOrNull()?.let{it>0}==true&&image.isNotBlank(),onClick={onSave(n,pr.toDouble(),cat,image,stock.toInt())},colors=ButtonDefaults.buttonColors(containerColor=KadaiPurple)){Text(tr(language,"Simpan","Save"))}},dismissButton={TextButton(onDismiss){Text(tr(language,"Batal","Cancel"))}})}
